<script setup lang="ts">
// DraftPreviewPanel (US-204).
//
// The editable preview-draft panel for a server-authoritative unsaved draft
// generated by the workbench (single search or direct fallback). It renders
// the same Overview/Source/Filter/Seeds sections as the saved Request detail
// panel (US-203) but in "订阅草案（未保存）" mode:
//
//   - the always-visible 编辑订阅草案 form (字幕组/包含/排除/正则/大小写/
//     folder_name) calls the dry-run `preview-modify` endpoint, which
//     recomputes seed display without persisting;
//   - 保存草案 reserves the draft through `preview-save` (US-212: persist
//     first, replay-tombstone after; a failed disk write keeps the draft for
//     retry) and emits `saved` so the workbench can hand the user to the
//     saved-Request list/detail.
//
// Security boundary (US-194): the client holds only the opaque `draft_id`
// (component-local memory, never URL/browser storage/logs) plus the display
// snapshot; the authoritative draft lives in the server DraftStore. The
// full Request snapshot is never sent back to preview-modify/preview-save.
// `draft_*` failures (expired/evicted/replayed) show a fixed Chinese
// "请重新生成" hint and emit `expired` so the workbench restores the
// search/candidate state.
import { computed, ref } from 'vue'

import { api } from '@/api/client'
import type { operations } from '@/api/generated/api'
import { useNotificationStore } from '@/app/stores/notification'
import BaseButton from '@/components/forms/BaseButton.vue'
import BaseInput from '@/components/forms/BaseInput.vue'
import CheckboxRow from '@/components/forms/CheckboxRow.vue'
import FormField from '@/components/layout/FormField.vue'
import PanelSection from '@/components/layout/PanelSection.vue'
import LoadingState from '@/components/feedback/LoadingState.vue'
import { useDraftSession, type DraftPatch } from '@/app/composables/useDraftSession'

import {
  collectPreviewEditPatch,
  type PreviewEditState,
} from '@/features/workbench/candidateSearch'
import { displayValue, effectiveSeeds, excludedSeeds, completeSeedGroups, type RequestSnapshot } from '@/features/requests/requestDetail'
import { statusLabel } from '@/features/requests/requestsList'
import { storageQuery } from '@/features/requests/requestStorage'
import ResourceSummary from '@/features/workbench/ResourceSummary.vue'
import SubtitleGroupSelect from '@/features/workbench/SubtitleGroupSelect.vue'

type PreviewModifyResult = NonNullable<
  operations['previewModifyRequest']['responses']['200']['content']['application/json']['result']
>
type PreviewSaveResult = NonNullable<
  operations['previewSaveRequest']['responses']['200']['content']['application/json']['result']
>

const props = defineProps<{
  request: RequestSnapshot
  draftId: string
  draftRevision?: number
}>()

const emit = defineEmits<{
  (e: 'saved', requestId: string): void
  (e: 'expired'): void
  (e: 'failed'): void
  // US-211: the server-authoritative draft revision changed after a modify.
  // Parents track draft_id/draft_revision in component memory only so a
  // remount (e.g. re-opening a batch card) keeps the true base_revision.
  (e: 'changed', state: { request: RequestSnapshot; draftId: string; draftRevision: number }): void
}>()

const notification = useNotificationStore()

// Component-local draft state: the display snapshot is refreshed after every
// preview-modify, and the opaque draft_id / draft_revision are kept in memory
// only (never URL/browser storage/logs).
const session = useDraftSession({
  request: props.request,
  draftId: props.draftId,
  draftRevision: props.draftRevision,
})
// Keep one render-safe snapshot while the parent processes the invalidation
// event. The session itself is still cleared immediately and can no longer
// issue writes; this only prevents a transient Vue render from dereferencing
// null before the compatibility host removes the panel.
const draftSnapshot = computed(() => (session.request.value ?? props.request) as RequestSnapshot)
const draftCapability = session.draftId
const draftRevisionState = session.draftRevision
const applying = session.applying
const saving = ref(false)
const formError = ref('')

// Editable preview-edit form state (legacy `collectPreviewEditPatch`).
const editGroup = ref('')
const editMustContain = ref('')
const editMustNotContain = ref('')
const editUseRegex = ref(false)
const editCaseSensitive = ref(false)
const editFolderName = ref('')

function resetEditForm(): void {
  editGroup.value = draftSnapshot.value.confirmable_config?.selected_subtitle_group ?? ''
  editMustContain.value = draftSnapshot.value.confirmable_config?.filter_rule?.must_contain ?? ''
  editMustNotContain.value = draftSnapshot.value.confirmable_config?.filter_rule?.must_not_contain ?? ''
  editUseRegex.value = draftSnapshot.value.confirmable_config?.filter_rule?.use_regex === true
  editCaseSensitive.value = draftSnapshot.value.confirmable_config?.filter_rule?.case_sensitive === true
  editFolderName.value = draftSnapshot.value.confirmable_config?.expected_folder_name ?? ''
}

resetEditForm()

const groupOptions = computed(() => {
  const sources = draftSnapshot.value.source_info?.rss_sources ?? []
  return sources.map((source) => ({
    value: source.subtitle_group ?? '',
    label: source.subtitle_group ?? '未知字幕组',
  }))
})

const effective = computed(() => effectiveSeeds(draftSnapshot.value))
const excluded = computed(() => excludedSeeds(draftSnapshot.value))
const completeGroups = computed(() => completeSeedGroups(draftSnapshot.value))
const selectedGroupName = computed(
  () => draftSnapshot.value.confirmable_config?.selected_subtitle_group ?? '未选择字幕组',
)

function currentEditState(): PreviewEditState {
  return {
    selectedSubtitleGroup: editGroup.value,
    mustContain: editMustContain.value.trim(),
    mustNotContain: editMustNotContain.value.trim(),
    useRegex: editUseRegex.value,
    caseSensitive: editCaseSensitive.value,
    expectedFolderName: editFolderName.value.trim(),
  }
}

function originalEditState(): PreviewEditState {
  const config = draftSnapshot.value.confirmable_config
  return {
    selectedSubtitleGroup: config?.selected_subtitle_group ?? '',
    mustContain: config?.filter_rule?.must_contain ?? '',
    mustNotContain: config?.filter_rule?.must_not_contain ?? '',
    useRegex: config?.filter_rule?.use_regex === true,
    caseSensitive: config?.filter_rule?.case_sensitive === true,
    expectedFolderName: config?.expected_folder_name ?? '',
  }
}

/** True when the error type is one of the 409 draft_* regeneration conflicts. */
function isDraftError(error: unknown): boolean {
  const type = (error as { type?: string } | null)?.type ?? ''
  return (
    type === 'draft_expired' ||
    type === 'draft_evicted' ||
    type === 'draft_replayed' ||
    type === 'draft_revision_conflict'
  )
}

function notifyDraftExpired(): void {
  notification.error('订阅草案已失效', '请重新生成订阅草案后再试。')
  emit('expired')
}

function handleModifyFailure(): void {
  if (session.invalid.value) {
    notifyDraftExpired()
    return
  }
  formError.value = session.error.value?.message ?? '订阅草案修改失败，请稍后重试。'
  notification.error('修改失败', '订阅草案修改失败，请稍后重试。')
  emit('failed')
}

function handleModifySuccess(result: PreviewModifyResult): PreviewModifyResult {
  resetEditForm()
  emit('changed', {
    request: draftSnapshot.value,
    draftId: draftCapability.value ?? '',
    draftRevision: draftRevisionState.value ?? 1,
  })
  notification.success('已应用修改', '订阅草案种子展示已重新计算。')
  return result
}

async function retryModify(): Promise<void> {
  formError.value = ''
  const result = await session.retry()
  if (result) {
    handleModifySuccess(result)
  } else if (session.invalid.value || session.error.value) {
    handleModifyFailure()
  }
}

function resetFailedModify(): void {
  session.reset()
  formError.value = ''
  resetEditForm()
}

async function applyModify(): Promise<PreviewModifyResult | null> {
  const patch = collectPreviewEditPatch(originalEditState(), currentEditState())
  if (!Object.keys(patch).length) {
    formError.value = '请至少修改一个字段。'
    return null
  }
  formError.value = ''
  const result = await session.apply(patch as DraftPatch, storageQuery().storage_dir ?? null)
  if (!result) {
    handleModifyFailure()
    return null
  }
  return handleModifySuccess(result)
}

async function saveDraft(): Promise<void> {
  saving.value = true
  formError.value = ''
  try {
    // US-194: if the user has pending edits, apply them first (preview-modify
    // keeps the server-side draft in sync) so preview-save persists exactly
    // what the user reviewed — mirroring the legacy save button. US-211: the
    // modify carries the current base_revision and refreshes the in-memory
    // draft_revision for the save.
    const patch = collectPreviewEditPatch(originalEditState(), currentEditState())
    if (Object.keys(patch).length) {
      const modified = await modifyWithRevision()
      if (!modified) return
    }
    const saved = await api.post<PreviewSaveResult>('/api/v1/requests/preview-save', {
      body: {
        draft_id: draftCapability.value ?? '',
        // US-212: the save reserves the draft against the base_revision the
        // server last issued, so a concurrent modify cannot move the revision
        // out from under the persist; on a failed disk write the server keeps
        // this draft/revision alive for a retry.
        base_revision: draftRevisionState.value ?? 1,
        storage_dir: storageQuery().storage_dir ?? null,
      },
    })
    // The draft was consumed by the save; clear the in-memory capability so a
    // replay can never reference a stale draft.
    draftCapability.value = ''
    const savedRequestId = saved?.request?.request_id
    if (savedRequestId) {
      emit('saved', savedRequestId)
    } else {
      emit('failed')
    }
  } catch (error) {
    void error
    if (isDraftError(error)) {
      notifyDraftExpired()
      return
    }
    notification.error('保存失败', '订阅草案保存失败，请稍后重试。')
    emit('failed')
  } finally {
    saving.value = false
  }
}

/**
 * Apply the pending edit form through preview-modify with the current
 * base_revision and refresh the in-memory draft_id/draft_revision/snapshot.
 * Returns false when the modify failed (the shared error/expired handling has
 * already fired); true when the server draft is now in sync with the form.
 */
async function modifyWithRevision(): Promise<boolean> {
  const patch = collectPreviewEditPatch(originalEditState(), currentEditState())
  if (!Object.keys(patch).length) return true
  const modified = await session.apply(patch as DraftPatch, storageQuery().storage_dir ?? null)
  if (!modified) {
    handleModifyFailure()
    return false
  }
  handleModifySuccess(modified)
  return true
}

/** Batch helper (US-205): save the draft and return the persisted snapshot.
 *
 * Mirrors ``saveDraft`` but returns the saved Request so the batch accept flow
 * can hand it to the accept endpoint without a second preview-save round trip.
 * Returns ``null`` when the save failed (the shared error handling already
 * fired the notification/expired events).
 */
async function saveDraftAndReturn(): Promise<RequestSnapshot | null> {
  saving.value = true
  formError.value = ''
  try {
    const patch = collectPreviewEditPatch(originalEditState(), currentEditState())
    if (Object.keys(patch).length) {
      const modified = await modifyWithRevision()
      if (!modified) return null
    }
    const saved = await api.post<PreviewSaveResult>('/api/v1/requests/preview-save', {
      body: {
        draft_id: draftCapability.value ?? '',
        // US-212: the save reserves the draft against the base_revision the
        // server last issued, so a concurrent modify cannot move the revision
        // out from under the persist; on a failed disk write the server keeps
        // this draft/revision alive for a retry.
        base_revision: draftRevisionState.value ?? 1,
        storage_dir: storageQuery().storage_dir ?? null,
      },
    })
    draftCapability.value = ''
    const savedRequest = saved?.request as RequestSnapshot | undefined
    if (savedRequest?.request_id) {
      emit('saved', savedRequest.request_id)
      return savedRequest
    }
    emit('failed')
    return null
  } catch (error) {
    void error
    if (isDraftError(error)) {
      notifyDraftExpired()
      return null
    }
    notification.error('保存失败', '订阅草案保存失败，请稍后重试。')
    emit('failed')
    return null
  } finally {
    saving.value = false
  }
}

defineExpose({ request: draftSnapshot, draftId: draftCapability, draftRevision: draftRevisionState, saveDraftAndReturn })
</script>

<template>
  <PanelSection title="订阅方案详情" class="request-detail-panel draft-preview-panel">
    <div id="request-detail-container" class="request-detail" aria-live="polite" aria-relevant="additions text">
      <h3 class="request-detail-title">
        {{ draftSnapshot.input?.raw_title || draftSnapshot.source_info?.matched_bangumi?.title || '订阅方案' }}
      </h3>

      <div class="detail-actions" aria-label="订阅方案操作">
        <p class="field-help preview-mode-note">
          订阅草案（未保存）：可编辑下方订阅方案；点击「应用修改」重新计算种子展示，点击「保存草案」后进入待确认流程。
        </p>
        <BaseButton
          id="draft-save-button"
          variant="primary"
          :loading="saving || applying"
          @click="saveDraft"
        >
          保存草案
        </BaseButton>
      </div>

      <!-- ── editable preview form (always visible) ─────────────────── -->
      <form id="detail-preview-edit-form" class="detail-inline-form" @submit.prevent="applyModify">
        <h4 class="detail-form-heading">编辑订阅草案</h4>

        <FormField label="字幕组" inputId="preview-subtitle-group">
          <SubtitleGroupSelect
            v-model="editGroup"
            :options="groupOptions"
            :applying="applying"
          />
        </FormField>

        <FormField label="包含规则" inputId="preview-must-contain">
          <BaseInput
            id="preview-must-contain"
            v-model="editMustContain"
            type="text"
            placeholder="如 1080p（默认按字面匹配）"
          />
        </FormField>

        <FormField label="排除规则" inputId="preview-must-not-contain">
          <BaseInput
            id="preview-must-not-contain"
            v-model="editMustNotContain"
            type="text"
            placeholder="如 [v2]（默认按字面匹配）"
          />
        </FormField>

        <div class="filter-options">
          <CheckboxRow id="preview-filter-use-regex" v-model:checked="editUseRegex" label="使用正则" />
          <CheckboxRow
            id="preview-filter-case-sensitive"
            v-model:checked="editCaseSensitive"
            label="大小写敏感"
          />
        </div>
        <p class="field-help" id="preview-filter-help">
          默认按字面文本匹配且不区分大小写；勾选「使用正则」后按正则匹配，勾选「大小写敏感」后区分大小写。
        </p>

        <FormField label="folder_name" inputId="preview-folder-name">
          <BaseInput
            id="preview-folder-name"
            v-model="editFolderName"
            type="text"
            placeholder="期望存储目录名"
          />
        </FormField>

        <p v-if="formError" id="preview-edit-error" class="field-error" role="alert">
          {{ formError }}
        </p>

        <div v-if="session.canRetry.value" class="detail-form-recovery" role="group" aria-label="修改失败恢复">
          <BaseButton id="preview-retry-button" type="button" variant="secondary" :loading="applying" @click="retryModify">
            重试修改
          </BaseButton>
          <BaseButton id="preview-reset-button" type="button" variant="secondary" :disabled="applying" @click="resetFailedModify">
            恢复上次结果
          </BaseButton>
        </div>

        <div class="detail-form-actions">
          <BaseButton id="preview-apply-button" type="submit" variant="primary" :loading="applying">
            应用修改
          </BaseButton>
        </div>
      </form>

      <!-- ── Overview ──────────────────────────────────────────────── -->
      <section class="detail-section overview-section" aria-label="Overview">
        <h4 class="detail-section-heading">Overview</h4>
        <dl class="detail-grid">
          <div class="detail-row"><dt>request_id</dt><dd>{{ displayValue(draftSnapshot?.request_id) }}</dd></div>
          <div class="detail-row"><dt>状态</dt><dd>{{ statusLabel(draftSnapshot?.status) }}</dd></div>
          <div class="detail-row"><dt>保存状态</dt><dd>订阅草案（未保存）</dd></div>
          <div class="detail-row"><dt>原始标题</dt><dd>{{ displayValue(draftSnapshot?.input?.raw_title) }}</dd></div>
          <div class="detail-row">
            <dt>匹配标题</dt>
            <dd>{{ displayValue(draftSnapshot?.source_info?.matched_bangumi?.title) }}</dd>
          </div>
        </dl>
      </section>

      <!-- ── Source ────────────────────────────────────────────────── -->
      <section class="detail-section source-section" aria-label="Source">
        <h4 class="detail-section-heading">Source</h4>
        <dl class="detail-grid">
          <div class="detail-row">
            <dt>字幕组</dt>
            <dd>{{ displayValue(draftSnapshot?.confirmable_config?.selected_subtitle_group) }}</dd>
          </div>
          <div class="detail-row">
            <dt>RSS 来源</dt>
            <dd>{{ draftSnapshot?.confirmable_config?.selected_rss_url ? '已选择' : '未选择' }}</dd>
          </div>
          <div class="detail-row">
            <dt>匹配番剧标题</dt>
            <dd>{{ displayValue(draftSnapshot?.source_info?.matched_bangumi?.title) }}</dd>
          </div>
        </dl>
      </section>

      <!-- ── Filter ────────────────────────────────────────────────── -->
      <section class="detail-section filter-section" aria-label="Filter">
        <h4 class="detail-section-heading">Filter</h4>
        <dl class="detail-grid">
          <div class="detail-row">
            <dt>包含规则</dt>
            <dd>{{ displayValue(draftSnapshot?.confirmable_config?.filter_rule?.must_contain) }}</dd>
          </div>
          <div class="detail-row">
            <dt>排除规则</dt>
            <dd>{{ displayValue(draftSnapshot?.confirmable_config?.filter_rule?.must_not_contain) }}</dd>
          </div>
          <div class="detail-row">
            <dt>匹配模式</dt>
            <dd>{{ draftSnapshot?.confirmable_config?.filter_rule?.use_regex === true ? '正则' : '普通字符' }}</dd>
          </div>
          <div class="detail-row">
            <dt>大小写</dt>
            <dd>{{ draftSnapshot?.confirmable_config?.filter_rule?.case_sensitive === true ? '区分大小写' : '不区分大小写' }}</dd>
          </div>
          <div class="detail-row">
            <dt>folder_name</dt>
            <dd>{{ displayValue(draftSnapshot?.confirmable_config?.expected_folder_name) }}</dd>
          </div>
          <div class="detail-row">
            <dt>有效种子数</dt>
            <dd>{{ effective.length }}</dd>
          </div>
          <div class="detail-row">
            <dt>排除种子数</dt>
            <dd>{{ excluded.length }}</dd>
          </div>
        </dl>
      </section>

      <!-- ── Seeds ─────────────────────────────────────────────────── -->
      <section class="detail-section seeds-section" aria-label="Seeds">
        <h4 class="detail-section-heading">Seeds</h4>
        <ResourceSummary
          :effective-seeds="effective"
          :complete-groups="completeGroups"
          :excluded-seeds="excluded"
          :selected-group-name="selectedGroupName"
        />
      </section>
    </div>
    <LoadingState v-if="saving" message="正在保存订阅草案..." />
  </PanelSection>
</template>

